"""Main module for telemetry - interface with all its methods regarding metrics and traces."""

from typing import Callable, Dict, Sequence, Union

from taf.ul.telemetry.span import Span, BaseSpan
from taf.ul.telemetry.telemetry import BaseTelemetryAPI


class Telemetry:
    """Telemetry interface class which handles metrics/logs/traces collection and upload.

    Telemetry - TL.
    TL metrics, main resource, logger names are to be configured in yaml file on separate repository.
    TL uses this yaml file, loads it from the CONFIG repository and applies it. Once this is set up you can update the
    values of counters from config or log some data. Checkout examples - configuration and usage.
    """
    def __init__(self, tl: BaseTelemetryAPI):
        self._telemetry = tl

    # Metrics

    def update(
        self,
        counter_id,
        value: Union[int, float],
        metadata: Dict[str, Union[str, bool, float, int]] = None,
    ) -> bool:
        """Update the value of counter given by id.

        Value is dependent on the type of counter you have chosen to update:
         - regular counter(async as well): can only go up
         - up_down counter(async up down as well): can use negative values as well
         - gauge: can take any value
         - histogram: updates the statistics with the specified amount

        Metadata is used as a label - each metric can have many labels. The best practise is to have as little
        labels as possible as is it kills the performance of entire telemetry. The labels should represent the fixed
        value - it should have at max 10 values. I.e. metric total_my_test_executions may have
        a label: status - pass/fail.

        :param counter_id: A counter ID taken from yaml config from config repository.
        :param value: The value you want to update the counter with.
        :param metadata: Optional data describing counter.
        :return: Boolean value weather the update went successful.
        """
        metadata = metadata or {}
        return self._telemetry.update(counter_id, value, metadata)

    def add_counter_callback(self, counter_id: str, callbacks: Sequence[Callable]) -> bool:
        """Add callback to counter to be used asynchronously.

        :param counter_id: A counter ID taken from yaml config from config repository.
        :param callbacks: A sequence of callback to be attached to a counter to be called when updating counter.
        :return: Boolean value weather the attachment of callbacks went successful.
        """
        return self._telemetry.add_counter_callback(counter_id, callbacks)

    # Traces

    def start(self, name: str, **kwargs) -> BaseSpan:
        """To be used to start span manually and returns Span instance.

        The best practise is to use decorator or context manager but if you really need to start and stop manually use
        this method to create a Span. You will need to stop this Span manually by passing Span object to stop method.

        :param name: A Span name.
        :param kwargs: Optional data describing Span.
        :return: A Span instance.
        """
        return self._telemetry.start(name, **kwargs)

    def stop(self, span: Span):
        """To stop a span instance returned by start method

        :param span: A Span instance created by start method.
        """
        self._telemetry.stop(span)

    def trace(self, name: str, **kwargs):
        """Can be used as context manager or as a decorator to record an action

        Traces are measuring the time of an action. Every event you record during this action is logged as well.

        :param name: A Trace name.
        :param kwargs: Optional data describing Trace.
        """
        return self._telemetry.trace(name, **kwargs)
